mod solution;

fn main() {
    let cases = [
    (r#"stream=[4,5,8,2,10]"#, r#"4,4,5"#),
    (r#"stream=[9,8,7,6]"#, r#"7,7"#),
    (r#"
stream=[9,8,7,6]
"#, r#"7,7"#),
    (r#"  
stream=[4,5,8,2,10]
  "#, r#"4,4,5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS kth-stream");
}
